import React, { useEffect,useRef, useState } from "react";
import * as NavigationBar from "expo-navigation-bar";
import { NavigationContainer } from "@react-navigation/native";
import { createBottomTabNavigator } from "@react-navigation/bottom-tabs";
import { View, StyleSheet, Animated } from "react-native";
import * as SystemUI from 'expo-system-ui';
import { StatusBar } from "expo-status-bar";

// Páginas
import Home from "./Screens/Home";
import Login from "./Screens/Login";
import Rotas from "./Screens/Rotas";
import Loja from "./Screens/Loja";
import Contato from "./Screens/Contato";
import Cadastro from "./Screens/Cadastro";

// Menu fixo
import BottomMenu from "./elements/BottomMenu";

const Tab = createBottomTabNavigator();

export default function App() {
useEffect(() => {
  const hideNavigationBar = async () => {
    try {
      await SystemUI.setBackgroundColorAsync("black");
      await NavigationBar.setBehaviorAsync("inset-swipe");
      await NavigationBar.setVisibilityAsync("hidden");
    } catch (error) {
      console.warn("Erro ao esconder NavigationBar:", error);
    }
  };

  hideNavigationBar();
}, []);

  return (
    <NavigationContainer>
      <StatusBar hidden />
      <View style={styles.container}>
        <Tab.Navigator
          screenOptions={{ headerShown: false, tabBarStyle: { display: "none" } }}
        >
          <Tab.Screen name="Home" component={Home} />
          <Tab.Screen name="Login" component={Login} />
          <Tab.Screen name="Rotas" component={Rotas} />
          <Tab.Screen name="Loja" component={Loja} />
          <Tab.Screen name="Contato" component={Contato} />
          <Tab.Screen name="Register" component={Cadastro} />
        </Tab.Navigator>

        {/* Menu fixo visível em todas as telas */}
        <BottomMenu />
      </View>
    </NavigationContainer>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
  },
});
